def duplicateCharsImp : String → String :=
fun s =>
  (have acc := "";
    do
    let r ←
      forIn s.data acc fun c r =>
          have acc := r;
          have acc := (acc.push c).push c;
          do
          pure PUnit.unit
          pure (ForInStep.yield acc)
    have acc : String := r
    pure acc).run
def duplicateCharsImpL : String → List Char :=
fun s =>
  (have acc := [];
    do
    let r ←
      forIn s.data acc fun c r =>
          have acc := r;
          have acc := acc ++ [c, c];
          do
          pure PUnit.unit
          pure (ForInStep.yield acc)
    have acc : List Char := r
    pure acc).run

